import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`roadmap-builder`,heroTitle:`Build your product roadmap in minutes`,heroSubtitle:`Perplexity Computer researches the market, prioritizes your initiatives, and turns them into a quarterly roadmap with themes, timelines, and stakeholder rationale.`,inputUrlCta:`Build this roadmap`,inputUrlPlaceholder:`e.g. yourproduct.com or a planning doc URL`,inputUrlPrefill:`Go to {url} and build a quarterly product roadmap. (1) Understand the product, business goals, and the top feature requests or strategic initiatives under consideration. (2) Research competitor roadmaps, launches, and market direction to understand the landscape. (3) Prioritize the candidate work with a RICE-style framework and explain the rationale. (4) Organize the work into quarterly themes, timelines, and sequencing recommendations. (5) Deliver a roadmap document with priorities, stakeholder justification, and major tradeoffs called out clearly.`,heroOverlaySteps:[`Reviewing the product, strategic goals, and candidate initiatives for the roadmap`,`Researching competitor moves and market signals that should shape prioritization`,`Ranking initiatives and organizing them into themes, sequence, and timeline`,`Quarterly roadmap with rationale and tradeoffs ready for stakeholder review`],generatingSteps:[`Analyzing {url} to understand the product, current positioning, and planning context`,`Designing an agent to research competitor signals and compare roadmap opportunities`,`Configuring prioritization logic, themes, timing, and stakeholder justification`,`Packaging the output into a quarterly roadmap your team can use in planning conversations`],featureSectionTitle:`From idea pile to roadmap story`,featureCardTitles:[`Connects to your planning workflow`,`Outputs your team can present`],featureCardDescriptions:[`Computer breaks the work into market research, prioritization, roadmap sequencing, and rationale writing so the roadmap is more than a list of requests.`,`Notion, Docs, Sheets, Jira, and planning decks can stay connected so the roadmap flows into the rest of your product process.`,`Quarter themes. Prioritized initiatives. Timeline recommendations. Stakeholder rationale. Computer delivers a roadmap your team can defend in planning meetings.`],capabilitySectionTitle:`Your roadmap strategist, on demand`,capabilitySectionSubtitle:`Share the product context and come back to a roadmap with real prioritization behind it.`,capabilityCards:[{title:`Market Landscape Research`,description:`Computer can research competitor launches and market shifts so the roadmap reflects what is changing around your product.`},{title:`Initiative Prioritization`,description:`Computer can score candidate work by impact, confidence, and effort so the roadmap favors bets worth making.`},{title:`Theme & Timeline Planning`,description:`Computer can group work into coherent roadmap themes and recommend sequencing that matches product strategy.`},{title:`Connect Your Tools`,description:`Computer can push the roadmap into planning docs and collaboration tools so product, design, and engineering stay aligned.`},{title:`Stakeholder Rationale`,description:`Computer can explain why each initiative belongs on the roadmap and what tradeoffs come with that choice.`},{title:`Quarterly Refresh`,description:`Computer can revisit the roadmap later, compare new signals, and update the plan as priorities shift.`}]});export{t as default};
